<?php
/** Behavioral integration tests; run with PHP8 CLI (sockets enables transport cases). */
declare(strict_types=1);
$public=__DIR__.'/../webui/web/public';
if (!is_file($public.'/ip-health-store.php')) {fwrite(STDERR,"FAIL missing IP health store\n");exit(1);}
require_once $public.'/ip-health-store.php';
require_once $public.'/ip-health-probe.php';
require_once $public.'/ip-health-controller.php';
require_once $public.'/ip-health-api.php';
function same(mixed $want,mixed $got,string $why):void {if($want!==$got)throw new RuntimeException($why.' expected '.json_encode($want).' got '.json_encode($got));}
function truth(bool $value,string $why):void {same(true,$value,$why);}
function fails(callable $fn,string $code):void {try{$fn();}catch(Throwable $e){same($code,$e->getMessage(),'error code');return;}throw new RuntimeException('expected '.$code);}
function rmTree(string $dir):void {if(is_link($dir)||is_file($dir)){unlink($dir);return;}if(!is_dir($dir))return;foreach(scandir($dir) as $n)if($n!=='.'&&$n!=='..')rmTree($dir.'/'.$n);rmdir($dir);}
function fixture():array {$root=sys_get_temp_dir().'/ip-health-test-'.bin2hex(random_bytes(8));mkdir($root,0700);return [$root,new NfqwsIpHealthStore($root.'/state',$root.'/run')];}
define('NOW',time());
const GEN='wan-a';
class ScriptedIpHealthProbe extends NfqwsIpHealthProbe {public array $calls=[];public array $answers=[];public function check(string $ip,string $sni,string $interface):string {$this->calls[]=[$ip,$sni,$interface];return array_shift($this->answers)??'unknown';}}
function events(int $at=NOW,string $ip='93.184.216.34'):array {return [['kind'=>'silent','at'=>$at,'ip'=>$ip,'client_port'=>40001,'host'=>'example.com'],['kind'=>'silent','at'=>$at,'ip'=>$ip,'client_port'=>40002,'host'=>'example.com']];}
function incident(NfqwsIpHealthStore $store,int $at=NOW,string $gen=GEN,string $ip='93.184.216.34'):void {$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];(new NfqwsIpHealthController($store,$p))->tick($at,$gen,'eth0',events($at,$ip));}
function seedRecheckIncidents(NfqwsIpHealthStore $store,int $count):void {
    $store->transaction(function(array &$v)use($count){$v['generation']=GEN;for($i=0;$i<$count;$i++){
        $ip='8.8.'.intdiv($i,256).'.'.($i%256);$id=substr(hash('sha256',$ip),0,32);
        $v['entries'][$id]=['id'=>$id,'ip'=>$ip,'port'=>443,'host'=>'example.com','until'=>NOW+86400,'first_seen'=>NOW,'incident'=>1,'last_check'=>NOW,'check_state'=>'silent','generation'=>GEN,'successes'=>0];$v['history'][$ip]=NOW;
    }},NOW);
}
$tests=[];
$tests['empty status has exact schema and reads without creating storage']=function(){[$root,$s]=fixture();try{$v=$s->status(NOW);same(['schema_version','revision','enabled','runtime','entries'],array_keys($v),'status keys');same(1,$v['schema_version'],'schema');truth((bool)preg_match('/^[a-f0-9]{64}$/D',$v['revision']),'revision');same(true,$v['enabled'],'default enabled');same(['state'=>'stopped','code'=>null,'updated_at'=>null,'dns'=>'unavailable'],$v['runtime'],'runtime default');same([],$v['entries'],'empty');same(false,is_dir($root.'/state'),'read only');}finally{rmTree($root);}};
$tests['explicit unchanged enable persists consent but status remains read only']=function(){[$root,$s]=fixture();try{$before=$s->status(NOW);same(false,is_file($root.'/state/bans.json'),'absent before selection');$after=$s->configure(true,$before['revision'],NOW);same($before,$after,'unchanged visible setting');truth(is_file($root.'/state/bans.json'),'explicit default selection is durable');$raw=json_decode(file_get_contents($root.'/state/bans.json'),true);same(true,$raw['enabled'],'saved enable');same(0600,fileperms($root.'/state/bans.json')&0777,'private journal');$stamp=filemtime($root.'/state/bans.json');$s->status(NOW+1);same($stamp,filemtime($root.'/state/bans.json'),'poll does not rewrite');}finally{rmTree($root);}};
$tests['configure requests reconcile after lease release and never from status or stale selection']=function(){[$root,$s]=fixture();try{$calls=0;$leasePath=$root.'/update.lock';$lease=function()use($leasePath){$f=fopen($leasePath,'c+');truth(flock($f,LOCK_SH|LOCK_NB),'lease acquired');return $f;};$notify=function()use(&$calls,$leasePath){$f=fopen($leasePath,'c+');truth(flock($f,LOCK_EX|LOCK_NB),'reconcile begins after release');flock($f,LOCK_UN);fclose($f);$calls++;return true;};$api=new NfqwsIpHealthApi($s,$lease,$notify,fn()=>['state'=>'ready','code'=>null]);$v=$api->handle(['cmd'=>'iphealthstatus','csrf_token'=>'x']);same(0,$calls,'status never launches worker');$api->handle(['cmd'=>'iphealthconfigure','csrf_token'=>'x','enabled'=>'0','revision'=>$v['revision']]);same(1,$calls,'one configure queues reconcile');fails(fn()=>$api->handle(['cmd'=>'iphealthconfigure','csrf_token'=>'x','enabled'=>'1','revision'=>$v['revision']]),'stale_revision');same(1,$calls,'stale configure never launches');}finally{rmTree($root);}};
$tests['capability preparation is visible without changing saved enabled history']=function(){[$root,$s]=fixture();try{$v=$s->status(NOW);$s->configure(true,$v['revision'],NOW);$before=file_get_contents($root.'/state/bans.json');$api=new NfqwsIpHealthApi($s,fn()=>null,fn()=>true,fn()=>['state'=>'pending','code'=>null]);$v=$api->handle(['cmd'=>'iphealthstatus','csrf_token'=>'x']);same('starting',$v['runtime']['state'],'preparation state');same('socket_preparing',$v['runtime']['code'],'friendly capability code');same($before,file_get_contents($root.'/state/bans.json'),'status preserves journal');$api=new NfqwsIpHealthApi($s,fn()=>null,fn()=>true,fn()=>['state'=>'failed','code'=>'/private/raw-error']);same('socket_setup_failed',$api->handle(['cmd'=>'iphealthstatus','csrf_token'=>'x'])['runtime']['code'],'private failure sanitized');$s->configure(false,$s->status(NOW)['revision'],NOW);same('stopped',$api->handle(['cmd'=>'iphealthstatus','csrf_token'=>'x'])['runtime']['state'],'off remains stopped');}finally{rmTree($root);}};
$tests['independent silence confirms one day and duplicate packets do not escalate']=function(){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW,GEN,'eth0',[events()[0],events()[0]]);same([],$s->status(NOW)['entries'],'one flow ignored');same([],$p->calls,'no probe for duplicate');$c->tick(NOW,GEN,'eth0',[events()[1]]);$e=$s->status(NOW)['entries'][0];same(443,$e['port'],'port');same(NOW+86400,$e['until'],'first duration');same(1,$e['incident'],'first incident');same(NOW,$e['first_seen'],'first seen');same('silent',$e['check_state'],'confirmation');same(['id','ip','port','host','until','first_seen','incident','last_check','check_state'],array_keys($e),'entry schema');$rev=$s->status(NOW)['revision'];$c->tick(NOW+1,GEN,'eth0',events(NOW+1));same($rev,$s->status(NOW+1)['revision'],'no active escalation');same(3,count($p->calls),'bounded probes');same('eth0',$p->calls[0][2],'same interface');truth($p->calls[1][1]!==$p->calls[2][1],'independent SNI');}finally{rmTree($root);}};
$tests['new incident escalates within history and old history expires']=function(){[$root,$s]=fixture();try{incident($s);same([],$s->status(NOW+86401)['entries'],'expired invisible');incident($s,NOW+86401);same(NOW+86401+604800,$s->status(NOW+86401)['entries'][0]['until'],'repeat seven days');same(2,$s->status(NOW+86401)['entries'][0]['incident'],'repeat count');incident($s,NOW+40*86400);same(1,$s->status(NOW+40*86400)['entries'][0]['incident'],'history evicted');}finally{rmTree($root);}};
$tests['reply unknown control failure private endpoints and bad time cannot ban']=function(){foreach([['replied','silent','replied'],['unknown','silent','silent'],['silent','silent','silent'],['replied','unknown','silent']] as $answers){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=$answers;(new NfqwsIpHealthController($s,$p))->tick(NOW,GEN,'eth0',events());same([],$s->status(NOW)['entries'],'fail open evidence');}finally{rmTree($root);}}foreach(['127.0.0.1','10.0.0.1','192.168.1.1','169.254.1.1','::1','fc00::1','2001:db8::1','224.0.0.1','100.64.0.1'] as $ip){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];(new NfqwsIpHealthController($s,$p))->tick(NOW,GEN,'eth0',events(NOW,$ip));same([],$p->calls,'private not probed '.$ip);}finally{rmTree($root);}}[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();(new NfqwsIpHealthController($s,$p))->tick(100,GEN,'eth0',events(100));same([],$p->calls,'unsane clock');same("IPHEALTH1\nexpires 100\nenabled 0\n",$s->manifest(100,GEN),'bad clock disabled');}finally{rmTree($root);}};
$tests['network generation suspends enforcement disabled mode preserves state']=function(){[$root,$s]=fixture();try{incident($s);$e=$s->status(NOW)['entries'][0];same("IPHEALTH1\nexpires ".(NOW+15)."\nenabled 1\nban 93.184.216.34 ".(NOW+86400)."\n",$s->manifest(NOW,GEN),'active manifest');same("IPHEALTH1\nexpires ".(NOW+15)."\nenabled 1\n",$s->manifest(NOW,'wan-b'),'new network');$s->configure(false,$s->status(NOW)['revision'],NOW);same(1,count($s->status(NOW)['entries']),'preserved');same("IPHEALTH1\nexpires ".(NOW+15)."\nenabled 0\n",$s->manifest(NOW,GEN),'disabled');}finally{rmTree($root);}};
$tests['three spaced responsive retests lift without extending duration']=function(){[$root,$s]=fixture();try{incident($s);$p=new ScriptedIpHealthProbe();$p->answers=['replied','replied','replied'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW+899,GEN,'eth0',[]);same([],$p->calls,'not due');for($i=1;$i<=3;$i++)$c->tick(NOW+900*$i,GEN,'eth0',[]);same([],$s->status(NOW+2700)['entries'],'three success lift');same(3,count($p->calls),'one retest each');incident($s,NOW+2800);same(2,$s->status(NOW+2800)['entries'][0]['incident'],'lift retains incident history');}finally{rmTree($root);}};
$tests['large silent lists recheck every address without insertion-order starvation']=function(){[$root,$s]=fixture();try{
    seedRecheckIncidents($s,512);$p=new ScriptedIpHealthProbe();$p->answers=array_fill(0,512,'silent');$c=new NfqwsIpHealthController($s,$p);
    // A real silent probe can take3s and the production worker sleeps1s.
    // Older checked entries become due again before the whole list completes.
    for($i=0;$i<512;$i++)$c->tick(NOW+900+4*$i,GEN,'eth0',[]);
    same(512,count($p->calls),'one bounded retest each tick');same(512,count(array_unique(array_column($p->calls,0))),'every address gets a turn before a repeat');
    foreach($s->status(NOW+900+4*511)['entries'] as $entry)truth($entry['last_check']>NOW,'no entry left untested');
}finally{rmTree($root);}};
$tests['explicit rechecks take priority over older automatic work']=function(){[$root,$s]=fixture();try{
    seedRecheckIncidents($s,2);$queued=substr(hash('sha256','8.8.0.1'),0,32);
    $s->transaction(function(array &$v)use($queued){$v['entries'][$queued]['last_check']=NOW+500;},NOW+500);
    $s->recheck($queued,$s->status(NOW+1000)['revision'],NOW+1000);
    $p=new ScriptedIpHealthProbe();$p->answers=['silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW+1000,GEN,'eth0',[]);
    same('8.8.0.1',$p->calls[0][0],'explicit queued address wins');same([],$s->view(NOW+1000)['recheck'],'one queued check consumed');
    $c->tick(NOW+1004,GEN,'eth0',[]);same('8.8.0.0',$p->calls[1][0],'older automatic address follows');
}finally{rmTree($root);}};
$tests['stale mutations reject and remove clear are bounded by revision']=function(){[$root,$s]=fixture();try{incident($s);$v=$s->status(NOW);$id=$v['entries'][0]['id'];fails(fn()=>$s->remove($id,str_repeat('0',64),NOW),'stale_revision');same($v,$s->status(NOW),'no stale write');$s->remove($id,$v['revision'],NOW);same([],$s->status(NOW)['entries'],'removed');fails(fn()=>$s->remove('../bad',$s->status(NOW)['revision'],NOW),'invalid_request');incident($s,NOW+1);$s->clear($s->status(NOW+1)['revision'],NOW+1);same([],$s->status(NOW+1)['entries'],'clear');}finally{rmTree($root);}};
$tests['recheck is a bounded queued operation without network from API']=function(){[$root,$s]=fixture();try{incident($s);$api=new NfqwsIpHealthApi($s,fn()=>null);$before=$s->status();$after=$api->handle(['cmd'=>'iphealthrecheck','csrf_token'=>'x','id'=>'all','revision'=>$before['revision']]);same('due',$after['entries'][0]['check_state'],'queued');same(count($before['entries']),count($after['entries']),'preserves entries');$p=new ScriptedIpHealthProbe();$p->answers=['replied'];(new NfqwsIpHealthController($s,$p))->tick(NOW+1,GEN,'eth0',[]);same(1,count($p->calls),'worker consumes queue');}finally{rmTree($root);}};
$tests['strict API schema and updater lease prevent writes']=function(){foreach([['cmd'=>'iphealthstatus','csrf_token'=>'x','url'=>'http://127.0.0.1'],['cmd'=>'iphealthconfigure','csrf_token'=>'x','enabled'=>'yes','revision'=>str_repeat('a',64)],['cmd'=>'iphealthclear','csrf_token'=>'x','revision'=>[]],['cmd'=>'iphealthrecheck','csrf_token'=>'x','id'=>'../x','revision'=>str_repeat('a',64)]] as $post)fails(fn()=>NfqwsIpHealthApi::validate($post),'invalid_request');[$root,$s]=fixture();try{$api=new NfqwsIpHealthApi($s,function(){throw new RuntimeException('busy');});$v=$s->status();same($v,$api->handle(['cmd'=>'iphealthstatus','csrf_token'=>'x']),'status no lease');fails(fn()=>$api->handle(['cmd'=>'iphealthconfigure','csrf_token'=>'x','enabled'=>'0','revision'=>$v['revision']]),'busy');same(true,$s->status()['enabled'],'lease rejection prevents mutation');same('invalid_state',NfqwsIpHealthApi::error(new RuntimeException('/private/path')),'sanitized errors');}finally{rmTree($root);}};
$tests['queued manual checks reject replay of the consumed revision']=function(){[$root,$s]=fixture();try{incident($s);$before=$s->status(NOW);$after=$s->recheck('all',$before['revision'],NOW);truth($after['revision']!==$before['revision'],'queue changes visible action revision');fails(fn()=>$s->recheck('all',$before['revision'],NOW),'stale_revision');$p=new ScriptedIpHealthProbe();$p->answers=['silent'];(new NfqwsIpHealthController($s,$p))->tick(NOW+1,GEN,'eth0',[]);fails(fn()=>$s->recheck('all',$before['revision'],NOW+1),'stale_revision');}finally{rmTree($root);}};
$tests['malformed symlink hardlink unsafe modes and writer contention reject']=function(){foreach(['json','symlink','hardlink','mode'] as $mode){[$root,$s]=fixture();try{incident($s);$file=$root.'/state/bans.json';$outside=$root.'/outside';file_put_contents($outside,'PRIVATE');chmod($outside,0600);if($mode==='json')file_put_contents($file,'{}');elseif($mode==='mode')chmod($file,0644);else{unlink($file);if($mode==='symlink')symlink($outside,$file);else link($outside,$file);}fails(fn()=>$s->status(NOW),'invalid_state');same('PRIVATE',file_get_contents($outside),'outside preserved');}finally{rmTree($root);}}[$root,$s]=fixture();try{incident($s);$f=fopen($root.'/state/state.lock','r+');flock($f,LOCK_EX);$start=microtime(true);fails(fn()=>$s->clear($s->status(NOW)['revision'],NOW),'busy');truth(microtime(true)-$start<2,'bounded contention');flock($f,LOCK_UN);fclose($f);}finally{rmTree($root);}};
$tests['runtime status is validated and stale active status becomes unavailable']=function(){[$root,$s]=fixture();try{incident($s);file_put_contents($root.'/run/runtime-status.json',json_encode(['state'=>'active','code'=>null,'updated_at'=>NOW,'dns'=>'router_udp']));chmod($root.'/run/runtime-status.json',0600);same('active',$s->status(NOW)['runtime']['state'],'fresh runtime');same('unavailable',$s->status(NOW+30)['runtime']['state'],'dead worker');file_put_contents($root.'/run/runtime-status.json','{"state":"active","code":"/secret","updated_at":null,"dns":"router_udp"}');same('unavailable',$s->status(NOW)['runtime']['state'],'malformed fail open');}finally{rmTree($root);}};
$tests['storage bound never exceeds 512 incidents']=function(){[$root,$s]=fixture();try{$s->transaction(function(array &$v){for($i=0;$i<513;$i++){$ip='8.8.'.intdiv($i,256).'.'.($i%256);$id=substr(hash('sha256',$ip),0,32);$v['entries'][$id]=['id'=>$id,'ip'=>$ip,'port'=>443,'host'=>'example.com','until'=>NOW+86400,'first_seen'=>NOW,'incident'=>1,'last_check'=>NOW,'check_state'=>'silent','generation'=>GEN,'successes'=>0];$v['history'][$ip]=NOW;}$v['generation']=GEN;},NOW);same(512,count($s->status(NOW)['entries']),'bounded storage');same(512,substr_count($s->manifest(NOW,GEN),"\nban "),'bounded manifest');}finally{rmTree($root);}};
$tests['both control endpoints are usable while a tick remains bounded']=function(){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=['unknown','replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW,GEN,'eth0',events());same([],$s->status(NOW)['entries'],'first control unavailable');$c->tick(NOW+1,GEN,'eth0',events(NOW+1));same(1,count($s->status(NOW+1)['entries']),'alternate responsive control');same('1.0.0.1',$p->calls[1][0],'alternate fixed endpoint');same(4,count($p->calls),'one then three checks');}finally{rmTree($root);}};
$tests['stale flow timestamps cannot combine and wrong network needs new evidence']=function(){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW,GEN,'eth0',[events()[0]]);$c->tick(NOW+61,GEN,'eth0',[events(NOW+61)[1]]);same([],$p->calls,'stale flow not independent evidence');incident($s,NOW+62);$before=$s->status(NOW+62)['entries'][0];$c->tick(NOW+100,'wan-b','eth0',[]);same(0,substr_count($s->manifest(NOW+100,'wan-b'),'ban '),'network suspended');$c->tick(NOW+101,'wan-b','eth0',events(NOW+101));same(1,substr_count($s->manifest(NOW+101,'wan-b'),'ban '),'fresh independently checked network');}finally{rmTree($root);}};
$tests['disabled observation is discarded before re-enabling']=function(){[$root,$s]=fixture();try{$s->configure(false,$s->status(NOW)['revision'],NOW);$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW,GEN,'eth0',[events()[0]]);$s->configure(true,$s->status(NOW)['revision'],NOW);$c->tick(NOW+1,GEN,'eth0',[events(NOW+1)[1]]);same([],$p->calls,'disabled evidence never collected');}finally{rmTree($root);}};
$tests['disable drops pending pre-toggle observations']=function(){[$root,$s]=fixture();try{$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW,GEN,'eth0',[events()[0]]);$s->configure(false,$s->status(NOW)['revision'],NOW);$s->configure(true,$s->status(NOW)['revision'],NOW);$c->tick(NOW+1,GEN,'eth0',[events(NOW+1)[1]]);same([],$p->calls,'new observation cannot combine with disabled evidence');}finally{rmTree($root);}};
$tests['network revalidation does not escalate an incident still in progress']=function(){[$root,$s]=fixture();try{incident($s);$first=$s->status(NOW)['entries'][0];incident($s,NOW+100,'wan-b');$new=$s->status(NOW+100)['entries'][0];same(1,$new['incident'],'active incident not repeated');same($first['until'],$new['until'],'network cannot extend duration');same(0,substr_count($s->manifest(NOW+100,GEN),'ban '),'stale worker generation cannot enforce');}finally{rmTree($root);}};
$tests['backwards wall clock cannot enforce future incidents']=function(){[$root,$s]=fixture();try{incident($s);same(0,substr_count($s->manifest(NOW-86400,GEN),'ban '),'future incident suspended on clock rollback');same([],$s->status(NOW-86400)['entries'],'future incident not active');}finally{rmTree($root);}};
$tests['toggle remove and clear synchronously revoke RAM enforcement']=function(){[$root,$s]=fixture();try{incident($s);$s->publishManifest(NOW,GEN);same(0644,fileperms($root.'/run/active.txt')&0777,'readable manifest mode');truth(str_contains(file_get_contents($root.'/run/active.txt'),'ban 93.184.216.34'),'initial active');$s->configure(false,$s->status(NOW)['revision'],NOW);truth(str_contains(file_get_contents($root.'/run/active.txt'),"enabled 0\n"),'toggle immediate');$s->publishManifest(NOW,GEN);truth(str_contains(file_get_contents($root.'/run/active.txt'),"enabled 0\n"),'worker cannot publish cached enabled state');$s->configure(true,$s->status(NOW)['revision'],NOW);$id=$s->status(NOW)['entries'][0]['id'];$s->remove($id,$s->status(NOW)['revision'],NOW);same(0,substr_count(file_get_contents($root.'/run/active.txt'),'ban '),'remove immediate');incident($s,NOW+1);$s->publishManifest(NOW+1,GEN);$s->clear($s->status(NOW+1)['revision'],NOW+1);same(0,substr_count(file_get_contents($root.'/run/active.txt'),'ban '),'clear immediate');}finally{rmTree($root);}};
$tests['web enable cannot activate stored bans without a ready worker']=function(){[$root,$s]=fixture();try{incident($s);$s->publishManifest(NOW,GEN);$s->configure(false,$s->status(NOW)['revision'],NOW);$s->configure(true,$s->status(NOW)['revision'],NOW);truth(str_contains(file_get_contents($root.'/run/active.txt'),"enabled 0\n"),'wait for worker capability verification');same(1,count($s->status(NOW)['entries']),'history preserved until readiness');}finally{rmTree($root);}};
$tests['manual recheck revalidates suspended network with control and two SNIs']=function(){[$root,$s]=fixture();try{incident($s);$p=new ScriptedIpHealthProbe();$p->answers=['replied','silent','silent'];$c=new NfqwsIpHealthController($s,$p);$c->tick(NOW+100,'wan-b','eth0',[]);$before=$s->status(NOW+100);$queued=$s->recheck('all',$before['revision'],NOW+100);truth($before['revision']!==$queued['revision'],'suspended queued action revision');$c->tick(NOW+101,'wan-b','eth0',[]);same(3,count($p->calls),'queued old-network recheck consumed');same(1,substr_count($s->manifest(NOW+101,'wan-b'),'ban '),'fresh revalidation permits enforcement');same(NOW+86400,$s->status(NOW+101)['entries'][0]['until'],'recheck keeps original incident deadline');}finally{rmTree($root);}};
$tests['simultaneous clear transactions have one winner and one stale editor']=function(){if(!function_exists('pcntl_fork'))return;[$root,$s]=fixture();try{incident($s);$revision=$s->status(NOW)['revision'];$children=[];for($i=0;$i<2;$i++){$pid=pcntl_fork();if($pid===0){try{$s->clear($revision,NOW);$result='ok';}catch(Throwable $e){$result=$e->getMessage();}file_put_contents($root.'/result-'.$i,$result);exit(0);}$children[]=$pid;}foreach($children as $pid)pcntl_waitpid($pid,$status);$actual=[file_get_contents($root.'/result-0'),file_get_contents($root.'/result-1')];sort($actual);same(['ok','stale_revision'],$actual,'serialized compare and swap');same([],$s->status(NOW)['entries'],'one clear committed');}finally{rmTree($root);}};
$tests['availability rejects malformed interface without probing']=function(){same(false,(new NfqwsIpHealthProbe())->availability("eth0\n"),'bad interface');};
$tests['TLS ClientHello framing contains bounded SNI and common TLS12 suites']=function(){$hello=NfqwsIpHealthProbe::clientHello('example.com');same(22,ord($hello[0]),'TLS handshake record');same(strlen($hello)-5,unpack('n',substr($hello,3,2))[1],'record length');same(1,ord($hello[5]),'ClientHello');same(strlen($hello)-9,unpack('N',"\0".substr($hello,6,3))[1],'handshake length');truth(str_contains($hello,"\x00\x0bexample.com"),'SNI name');truth(str_contains($hello,"\xc0\x2f"),'TLS12 suite');fails(fn()=>NfqwsIpHealthProbe::clientHello("example.com\n"),'invalid_request');same('unknown',(new NfqwsIpHealthProbe())->check('127.0.0.1','example.com',''),'public endpoint gate');};
if(function_exists('socket_create')&&function_exists('pcntl_fork')){
    class LocalIpHealthProbe extends NfqwsIpHealthProbe {protected function prepareSocket(mixed $socket,string $interface):bool{return true;}public function local(int $port):string{return $this->exchange('127.0.0.1','example.com','',$port);}}
    class RejectedMarkIpHealthProbe extends NfqwsIpHealthProbe {protected function prepareSocket(mixed $socket,string $interface):bool{return false;}public function local(int $port):string{return $this->exchange('127.0.0.1','example.com','',$port);}}
    $tests['actual TCP data EOF TLS alert reset and silence classify conservatively']=function(){foreach(['data','eof','alert','reset','silent'] as $behavior){$server=socket_create(AF_INET,SOCK_STREAM,SOL_TCP);socket_bind($server,'127.0.0.1',0);socket_listen($server,1);socket_getsockname($server,$address,$port);$pid=pcntl_fork();if($pid===0){$client=socket_accept($server);socket_close($server);$buf='';socket_recv($client,$buf,4096,0);if($behavior==='data')socket_write($client,'x');if($behavior==='alert')socket_write($client,"\x15\x03\x03\x00\x02\x02\x28");if($behavior==='reset')socket_set_option($client,SOL_SOCKET,SO_LINGER,['l_onoff'=>1,'l_linger'=>0]);if($behavior==='silent')usleep(3300000);socket_close($client);exit(0);}socket_close($server);$start=microtime(true);$answer=(new LocalIpHealthProbe())->local($port);pcntl_waitpid($pid,$status);same($behavior==='silent'?'silent':'replied',$answer,'socket '.$behavior);truth(microtime(true)-$start<4,'bounded socket '.$behavior);}};
    $tests['failed mark prevents even opening a TCP connection']=function(){$server=socket_create(AF_INET,SOCK_STREAM,SOL_TCP);socket_bind($server,'127.0.0.1',0);socket_listen($server,1);socket_getsockname($server,$address,$port);same('unknown',(new RejectedMarkIpHealthProbe())->local($port),'mark failure');socket_set_nonblock($server);same(false,@socket_accept($server),'no unmarked connect');socket_close($server);};
    $tests['availability rejects unavailable mark without a network connection']=function(){same(false,(new RejectedMarkIpHealthProbe())->availability('eth0'),'unavailable mark');same(true,(new LocalIpHealthProbe())->availability('eth0'),'usable transport boundary');same(false,(new LocalIpHealthProbe())->availability("eth0\n"),'invalid interface');};
}else echo "SKIP socket transport cases: sockets/pcntl unavailable\n";
$bad=0;foreach($tests as $name=>$test){try{$test();echo "PASS $name\n";}catch(Throwable $e){$bad++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}exit($bad?1:0);
